$run=Join-Path $root ('bootstrap/out/native-storage-ownership/'+[guid]::NewGuid().ToString('N'));$null=[IO.Directory]::CreateDirectory($run)
$inputs=@();$checks=@();$commands=@();$success=$false;$failure=$null;$utf8=[Text.UTF8Encoding]::new($false)
foreach($p in @($ReaderReport,$RetentionReport,$PSCommandPath,(Join-Path $PSScriptRoot 'storage-ownership-matrix.c'),(Join-Path $root 'bootstrap/tools/verification.ps1'))){$inputs+=Get-ArtifactIdentity $p}
function Retain($Id){$actual=Get-ArtifactIdentity $Id.path;if($actual.sha256 -cne $Id.sha256 -or $actual.bytes -ne $Id.bytes){throw ('Retained input changed: '+$Id.path)};$script:inputs+=@($actual);return $actual.path}
function Frozen([string]$Path){$ids=@(@($retention.inputs)+@($retention.artifacts)|Where-Object path -CEQ $Path);if($ids.Count -lt 1){throw ('Frozen artifact missing: '+$Path)};foreach($id in $ids){if($id.sha256 -cne $ids[0].sha256){throw 'Conflicting frozen identity'}};return Retain $ids[0]}
function Run([string]$File,[string[]]$Arguments,[int]$Timeout=180){$r=Invoke-BoundedProcess $File $Arguments $run $Timeout;$script:commands+=@($r);if($r.timedOut -or $r.exit -ne 0 -or $r.stderr -cne ''){throw ($r|ConvertTo-Json -Compress)};return $r.stdout}
function U16([byte[]]$Bytes,[int]$At){return [BitConverter]::ToUInt16($Bytes,$At)}
function U32([byte[]]$Bytes,[int]$At){return [long][BitConverter]::ToUInt32($Bytes,$At)}
function CString([byte[]]$Bytes,[int]$At){$end=$At;while($end -lt $Bytes.Length -and $Bytes[$end] -ne 0){++$end};if($end -eq $Bytes.Length){throw 'Unterminated independent string'};return [Text.Encoding]::UTF8.GetString($Bytes,$At,$end-$At)}
function FileOffset([long]$Rva,[int]$Length){$found=@($script:sections|Where-Object {$Rva -ge $_.rva -and $Rva+$Length -le $_.rva+[Math]::Min($_.virtual,$_.raw)});if($found.Count -ne 1){throw 'Independent initialized mapping is not unique'};return [int]($found[0].file+$Rva-$found[0].rva)}
function SymbolRva([string]$Name){if(-not $script:symbols.ContainsKey($Name) -or @($script:symbols[$Name]).Count -ne 1){throw ('Independent named anchor missing or ambiguous: '+$Name)};$symbol=$script:symbols[$Name][0];return [long]($script:sections[$symbol.section].rva+$symbol.offset)}
function Protect([long]$Rva,[long]$Bytes,[string]$Role){if($Bytes -lt 1 -or $Rva -lt 0 -or $Rva+$Bytes -gt $script:imageBytes){throw 'Independent protected range outside image'};$null=FileOffset $Rva $Bytes;$script:protected+=@([pscustomobject]@{rva=$Rva;bytes=$Bytes;role=$Role})}
function WriteExpected([string]$Path,$Rows){$stream=[IO.MemoryStream]::new();$writer=[IO.BinaryWriter]::new($stream);$names=[Text.StringBuilder]::new();foreach($row in $Rows){$null=$names.Append($row.name)};$writer.Write([int]$Rows.Count);$writer.Write([int]$names.Length);$first=0;foreach($row in $Rows){$writer.Write([int]$first);$writer.Write([int]$row.name.Length);foreach($field in @('unit','source','declaration','family','required','bytes','type','representation')){$writer.Write([int]$row.$field)};$first+=$row.name.Length};$writer.Write([Text.Encoding]::ASCII.GetBytes($names.ToString()));$writer.Flush();[IO.File]::WriteAllBytes($Path,$stream.ToArray());$writer.Dispose();$stream.Dispose()}
function WritePath($Writer,[string]$Path){$bytes=$utf8.GetBytes($Path);$Writer.Write([int]$bytes.Length);$Writer.Write($bytes)}
try {
 foreach($id in $reader.inputs){$null=Retain $id}
 foreach($name in @('probe.c','file-output-observed.c')){
  $ids=@($reader.artifacts|Where-Object {(Split-Path $_.path -Leaf) -ceq $name});if($ids.Count -ne 1){throw 'Reader bridge missing'};$source=Retain $ids[0]
  if($name -ceq 'probe.c'){$text=[IO.File]::ReadAllText($source);if(([regex]::Matches($text,'(?m)^int main\(')).Count -ne 1){throw 'Reader main bridge changed'};[IO.File]::WriteAllText((Join-Path $run 'reader-probe.c'),[regex]::Replace($text,'(?m)^int main\(','int binary_reader_main('),$utf8)}else{[IO.File]::Copy($source,(Join-Path $run $name))}
 }
 $executables=@();foreach($stage in 0..1){$ids=@($reader.artifacts|Where-Object {(Split-Path $_.path -Leaf) -ceq ('stage'+$stage+'-adapter.ll')});if($ids.Count -ne 1){throw 'Reader adapter missing'};$adapter=Retain $ids[0];$exe=Join-Path $run ('stage'+$stage+'-matrix.exe');$executables+=$exe;$null=Run $reader.acceptedSelection.clang.path @('--target=x86_64-w64-windows-gnu','-O2','-std=c17','-Wall','-Wextra','-Werror','-I',$run,'-I',$root,'-I',$PSScriptRoot,$adapter,(Join-Path $PSScriptRoot 'storage-ownership-matrix.c'),$reader.acceptedSelection.unicodeRuntime.path,'-o',$exe)}
 $images=@($retention.artifacts|Where-Object {(Split-Path $_.path -Leaf) -match '^stage[01]-[01]-O[02]-(Full|None)\.exe$'});if($images.Count -ne 16){throw 'Expected sixteen retained images'}
 foreach($id in $images){
  $image=Retain $id;$stem=[IO.Path]::GetFileNameWithoutExtension($image);if($stem -notmatch '^stage([01])-([01])-(O[02])-(Full|None)$'){throw 'Unexpected image name'};$generator=$Matches[1];$reference=$Matches[2];$optimization=$Matches[3];$debug=$Matches[4]
  $tables=@($retention.inputs|Where-Object {$_.path.EndsWith(('stage'+$generator+'\expected-definitions-'+$reference+'.tsv'))});if($tables.Count -ne 1){throw 'Complete producer table missing'};$table=Retain $tables[0];$rows=@(Import-Csv -LiteralPath $table -Delimiter "`t");if($rows.Count -ne 54){throw 'Complete frozen table missing'}
  $expected=Join-Path $run ($stem+'-complete.bin');WriteExpected $expected $rows
  $manifest=Join-Path $run ($stem+'-objects.bin');$writer=[IO.BinaryWriter]::new([IO.File]::Create($manifest));$writer.Write([int]9)
  foreach($kind in 0..6){$sources=@(-1);if($kind -eq 0){$sources=0..2};foreach($source in $sources){
   $object=Frozen (Join-Path (Split-Path $table -Parent) ('expected-'+$reference+'-'+$kind+'-'+$source+'-'+$optimization+'-'+$debug+'.o'));$writer.Write([int]$kind);$writer.Write([int]$source);WritePath $writer $object
   $unitFrozen=Frozen (Join-Path (Split-Path $image -Parent) ($stem+'-'+$kind+'-'+$source+'.bin'));$unitCopy=Join-Path $run ($stem+'-'+$kind+'-'+$source+'-expected.bin');WriteExpected $unitCopy @($rows|Where-Object {[int]$_.unit -eq $kind -and [int]$_.source -eq $source});if((Get-ArtifactIdentity $unitFrozen).sha256 -cne (Get-ArtifactIdentity $unitCopy).sha256){throw 'Complete table differs from frozen per-unit definitions'}
  }};$writer.Dispose()
  $b=[IO.File]::ReadAllBytes($image);$pe=U32 $b 60;$base=[BitConverter]::ToInt64($b,$pe+48);$imageBytes=U32 $b ($pe+80);$sectionTable=$pe+24+(U16 $b ($pe+20));$sections=@()
  for($i=0;$i -lt (U16 $b ($pe+6));++$i){$at=$sectionTable+40*$i;$sections+=@([pscustomobject]@{index=$i;rva=(U32 $b ($at+12));virtual=(U32 $b ($at+8));file=(U32 $b ($at+20));raw=(U32 $b ($at+16));flags=(U32 $b ($at+36))})}
  $symbols=@{};$sym=U32 $b ($pe+12);$symbolCount=U32 $b ($pe+16);$strings=$sym+18*$symbolCount
  for($i=0;$i -lt $symbolCount;){$at=$sym+18*$i;$section=U16 $b ($at+12);if((U32 $b $at) -eq 0){$name=CString $b ($strings+(U32 $b ($at+4)))}else{$name=[Text.Encoding]::UTF8.GetString($b,$at,8).TrimEnd([char]0)};if($section -gt 0 -and $section -le $sections.Count){if(-not $symbols.ContainsKey($name)){$symbols[$name]=@()};$symbols[$name]+=@([pscustomobject]@{index=$i;section=$section-1;offset=(U32 $b ($at+8));type=(U16 $b ($at+14))})};$i+=1+$b[$at+17]}
  $owners=@();for($i=0;$i -lt $rows.Count;++$i){$row=$rows[$i];if([int]$row.bytes -eq 0){continue};if(-not $symbols.ContainsKey($row.name) -or @($symbols[$row.name]).Count -ne 1){throw 'Independent generated storage anchor missing or ambiguous'};$symbol=$symbols[$row.name][0];$section=$sections[$symbol.section];$size=[int]$row.bytes;$rva=$section.rva+$symbol.offset;if($symbol.offset+$size -gt $section.virtual){throw 'Independent storage outside section'};$initialized=[Math]::Max(0,[Math]::Min($size,[Math]::Min($section.virtual,$section.raw)-$symbol.offset));$first=-1;if($initialized){$first=FileOffset $rva $initialized};$owners+=@([pscustomobject]@{row=$i;name=$row.name;symbol=$symbol.index;section=$symbol.section;first=$first;bytes=$size;initialized=$initialized;type=$symbol.type;offset=$symbol.offset;rva=$rva;address=$base+$rva;flags=$section.flags})}
  $owners=@($owners|Sort-Object rva);if($owners.Count -ne 16){throw 'Frozen generated storage census differs'};for($i=1;$i -lt $owners.Count;++$i){if($owners[$i-1].rva+$owners[$i-1].bytes -gt $owners[$i].rva){throw 'Frozen generated owners overlap'}}
  $protected=@();$refptrs=@($symbols.Keys|Where-Object {$_ -clike '.refptr.*'});if($refptrs.Count -ne 33){throw 'Frozen reference cell census differs'};foreach($name in $refptrs){if(@($symbols[$name]).Count -ne 1){throw 'Ambiguous reference cell'};$symbol=$symbols[$name][0];Protect ($sections[$symbol.section].rva+$symbol.offset) 8 ('reference cell '+$name)}
  # These seven pointer fields have exact eight-byte width in the independently
  # qualified image-relocation profile. No arbitrary CRT label gains an extent.
  foreach($name in @('__dyn_tls_init_callback','p.0','__imp___p___initenv','__imp__amsg_exit','__imp___getmainargs','__imp___initenv')){Protect (SymbolRva $name) 8 ('qualified CRT pointer '+$name)}
  Protect ((SymbolRva '__CTOR_LIST__')+8) 8 'qualified CRT constructor pointer'
  foreach($directory in @(@(1,'import descriptors'),@(3,'exception directory'),@(5,'relocation directory'),@(12,'IAT directory'))){$at=$pe+136+8*$directory[0];Protect (U32 $b $at) (U32 $b ($at+4)) $directory[1]}
  # AMD64 UNWIND_INFO: four-byte header, even slot padding, optional handler.
  # The frozen EH records use __C_specific_handler and SCOPE_TABLE_AMD64:
  # DWORD Count followed by Count * four-DWORD scope records (winnt.h/excpt.h).
  # Handler-specific payloads are bounded by that format, never by next symbols.
  $exceptionRva=U32 $b ($pe+160);$exceptionBytes=U32 $b ($pe+164);$unwindCount=0;$handlerCount=0;$unwindRecords=@()
  if($exceptionBytes%12 -ne 0){throw 'Independent runtime-function directory shape'}
  for($offset=0;$offset -lt $exceptionBytes;$offset+=12){$entry=FileOffset ($exceptionRva+$offset) 12;$unwind=U32 $b ($entry+8);$at=FileOffset $unwind 4;$version=$b[$at] -band 7;$flags=$b[$at] -shr 3;$slots=[int]$b[$at+2];if($version -ne 1 -or $flags -notin @(0,1)){throw 'Frozen unwind profile changed'};$width=4+2*($slots+($slots%2));$null=FileOffset $unwind $width
   $scopes=0;if($flags -eq 1){$handlerAt=FileOffset ($unwind+$width) 8;if((U32 $b $handlerAt) -ne (SymbolRva '__C_specific_handler')){throw 'Unqualified handler-specific metadata'};$scopes=U32 $b ($handlerAt+4);if($scopes -ne 1 -or $slots -ne 3){throw 'Frozen C-specific scope geometry differs'};$width+=8+16*$scopes;if($width -ne 36){throw 'Frozen EH extent differs'};++$handlerCount}
   $unwindRecords+=@([pscustomobject]@{rva=$unwind;bytes=$width;version=$version;flags=$flags;slots=$slots;scopes=$scopes})
   Protect $unwind $width 'unwind record and independently bounded handler metadata';++$unwindCount
  }
  $expectedUnwind=76;if($optimization -ceq 'O2'){$expectedUnwind=71};if($unwindCount -ne $expectedUnwind -or $handlerCount -ne 2){throw 'Frozen unwind metadata census differs'}
  $importRva=U32 $b ($pe+144);$importBytes=U32 $b ($pe+148);$descriptorCount=0;$dllCount=0;$apiCount=0;$ended=$false
  for($off=0;$off+20 -le $importBytes;$off+=20){$at=FileOffset ($importRva+$off) 20;$lookup=U32 $b $at;$dllRva=U32 $b ($at+12);$iat=U32 $b ($at+16);++$descriptorCount;if($lookup -eq 0 -and $dllRva -eq 0 -and $iat -eq 0){$ended=$true;break};$dll=CString $b (FileOffset $dllRva 1);Protect $dllRva ($utf8.GetByteCount($dll)+1) ('import DLL '+$dll);++$dllCount
   $items=0;while($true){if($items -gt 1000){throw 'Independent import census exceeded frozen profile'};$value=[BitConverter]::ToUInt64($b,(FileOffset ($lookup+8*$items) 8));if($value -eq 0){break};if($value -gt [long]::MaxValue){throw 'Frozen ordinal imports require a new explicit profile'};$hint=[long]$value;$api=CString $b (FileOffset ($hint+2) 1);Protect $hint ($utf8.GetByteCount($api)+3) ('import API '+$dll+'!'+$api);++$items;++$apiCount}
   Protect $lookup (($items+1)*8) ('import lookup '+$dll);Protect $iat (($items+1)*8) ('import address '+$dll)
  }
  if(-not $ended -or $descriptorCount -ne 10 -or $dllCount -ne 9 -or $apiCount -ne 47){throw 'Frozen independent import census differs'}
  $protected=@($protected|Sort-Object rva,bytes);if($protected.Count -ne 118+$expectedUnwind){throw 'Complete independently bounded protected census differs'}
  foreach($owner in $owners){foreach($span in $protected){if($owner.rva -lt $span.rva+$span.bytes -and $span.rva -lt $owner.rva+$owner.bytes){throw 'Frozen generated storage aliases protected metadata'}}}
  $oracle=Join-Path $run ($stem+'-oracle.bin');$writer=[IO.BinaryWriter]::new([IO.File]::Create($oracle));$writer.Write([int]$owners.Count);$writer.Write([int]$protected.Count);foreach($owner in $owners){foreach($field in @('row','symbol','section','first','bytes','initialized','type')){$writer.Write([int]$owner.$field)};foreach($field in @('offset','rva','address','flags')){$writer.Write([long]$owner.$field)}};foreach($span in $protected){$writer.Write([long]$span.rva);$writer.Write([long]$span.bytes)};$writer.Dispose()
  [pscustomobject]@{image=$id;table=(Get-ArtifactIdentity $table);owners=$owners;protected=$protected;unwind=[pscustomobject]@{count=$unwindCount;handlerCount=$handlerCount;records=$unwindRecords;literalProfile='Version 1, flags 0/1; 4-byte header; 2-byte slots padded to even count. Two flags 1 records each have 3 slots, a 4-byte __C_specific_handler RVA, a 4-byte scope count of 1, and one 16-byte scope record: 36 bytes total. This frozen-profile byte geometry is explicit in the gate; no installed SDK header is consumed.'};scope='Frozen generated owners and independently bounded metadata. TLS is validated inside the consumer. CRT labels do not imply positive storage extent. Unwind byte extents do not establish unwind or handler semantics.'}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $run ($stem+'-oracle.json')) -Encoding UTF8
  foreach($stage in 0..1){$output=Run $executables[$stage] @($image,$expected,$manifest,$oracle) 60;if($output -notmatch ('^PASS storage ownership 54 rows; 16 owners; '+$protected.Count+' protected; rejected 220; bytes [1-9][0-9]*; events [1-9][0-9]*\n$')){throw ('Unexpected ownership result: '+$output)};$checks+=@([pscustomobject]@{assertion='Complete producer-bound generated storage matches independent geometry and rejects per-owner aliases/discardability/geometry, incomplete order and protected overlap/shape controls';readerStage=$stage+1;image=$id;owners=16;protected=$protected.Count;rejected=220;passed=$true;output=$output})}
 }
 foreach($id in $inputs){$current=Get-ArtifactIdentity $id.path;if($current.sha256 -cne $id.sha256 -or $current.bytes -ne $id.bytes){throw ('Input changed during verification: '+$id.path)}};$success=$true
} catch {$failure=$_.Exception.Message}
[pscustomobject]@{success=$success;failure=$failure;acceptedSelection=$reader.acceptedSelection;inputs=$inputs;checks=$checks;commands=$commands;artifacts=@(Get-ChildItem -LiteralPath $run -File|ForEach-Object {Get-ArtifactIdentity $_.FullName});scope='Both readers, sixteen retained images, complete frozen definitions and independently bounded generated/protected storage. Protected completeness is established by the harness census, not inferred by the consumer. No arbitrary CRT extents, runtime write safety, dataflow or build/publication integration.'}|ConvertTo-Json -Depth 18|Set-Content (Join-Path $run 'report.json') -Encoding UTF8
Write-Output "Evidence: $run/report.json"
if(-not $success){throw $failure}
